 7451: function parseFieldGuide(md) {
 7452:   var sections = [];
 7453:   var cur = null;
 7454:   var lines = md.split("\n");
 7455:   for (var i = 0; i < lines.length; i++) {
 7456:     var line = lines[i];
 7457:     var h1 = line.match(/^# (.+)/);
 7458:     if (h1) {
 7459:       if (cur)
 7460:         sections.push({
 7461:           id: cur.id,
 7462:           h: cur.h,
 7463:           title: cur.title,
 7464:           body: cur.body.trim(),
 7465:         });
 7466:       var title = h1[1].trim();
 7467:       var id = title
 7468:         .toLowerCase()
 7469:         .replace(/[^a-z0-9]+/g, "_")
 7470:         .replace(/^_|_$/g, "");
 7471:       cur = { id: id, h: 1, title: title, body: "" };
 7472:     } else if (cur) {
 7473:       cur.body += line + "\n";
 7474:     }
 7475:   }
 7476:   if (cur)
 7477:     sections.push({
 7478:       id: cur.id,
 7479:       h: cur.h,
 7480:       title: cur.title,
 7481:       body: cur.body.trim(),
 7482:     });
 7483:   return sections.filter(function (s) {
 7484:     return s.body.length > 0;
 7485:   });
 7486: }
