 7604: function rbSearch(query) {
 7605:   const q = query.trim().toLowerCase();
 7606:   if (!q) {
 7607:     renderRulebookSection(
 7608:       RULEBOOK_SECTIONS.find(
 7609:         (s) => document.querySelector(".rbti.active")?.dataset?.id === s.id,
 7610:       ) || RULEBOOK_SECTIONS[0],
 7611:     );
 7612:     return;
 7613:   }
 7614:   const results = [];
 7615:   RULEBOOK_SECTIONS.forEach((s) => {
 7616:     if (s.title.toLowerCase().includes(q) || s.body.toLowerCase().includes(q))
 7617:       results.push(s);
 7618:   });
 7619:   const c = document.getElementById("rbcontent");
 7620:   if (!results.length) {
 7621:     c.innerHTML = '<p style="color:var(--dim)">No results found.</p>';
 7622:     return;
 7623:   }
 7624:   const re = new RegExp(`(${q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi");
 7625:   c.innerHTML = results
 7626:     .map((s) => `<h2>${s.title}</h2>${markdownToHtml(s.body)}`)
 7627:     .join(
 7628:       '<hr style="border:none;border-top:1px solid var(--bdr);margin:20px 0">',
 7629:     );
 7630:   c.querySelectorAll("td,th,p,li,blockquote").forEach((el) => {
 7631:     if (el.textContent.toLowerCase().includes(q))
 7632:       el.innerHTML = el.innerHTML.replace(re, '<span class="hl">$1</span>');
 7633:   });
 7634:   _wireRulebookLinks(c);
 7635: }
